from pathlib import Path
import json
css_path = Path('src/ui/styles/global.css')
css = css_path.read_text(encoding='utf-8')
if '/* Phase 17 — Living Earth */' not in css:
    css_path.write_text(css.rstrip() + '\n\n' + '\n/* Phase 17 — Living Earth */\n.desktop-left .layer-panel {\n  max-height: calc(100dvh - 178px);\n  overflow-y: auto;\n  scrollbar-width: thin;\n  scrollbar-color: var(--se-line-strong) transparent;\n}\n.weather-controls {\n  margin: 4px 7px 8px;\n  padding: 10px;\n  border: 1px solid var(--se-line);\n  border-radius: 10px;\n  background: rgba(0, 0, 0, .13);\n}\n.layer-control-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n}\n.layer-control-head > div { display: grid; gap: 3px; }\n.layer-control-head strong { font-size: .69rem; }\n.layer-control-head button {\n  min-height: 28px;\n  padding: 0 8px;\n  border: 1px solid var(--se-line);\n  border-radius: 7px;\n  background: rgba(255,255,255,.025);\n  color: var(--se-muted);\n  cursor: pointer;\n  font-size: .56rem;\n}\n.weather-toggle-list { display: grid; gap: 5px; margin-top: 9px; }\n.weather-toggle-list label {\n  min-height: 39px;\n  display: grid;\n  grid-template-columns: 1fr auto;\n  align-items: center;\n  gap: 10px;\n  padding: 6px 7px;\n  border: 1px solid var(--se-line);\n  border-radius: 8px;\n  background: rgba(255,255,255,.018);\n  cursor: pointer;\n}\n.weather-toggle-list label > span { display: grid; gap: 3px; min-width: 0; }\n.weather-toggle-list b { color: var(--se-text-soft); font-size: .61rem; font-weight: 620; }\n.weather-toggle-list small { color: var(--se-dim); font-size: .51rem; line-height: 1.3; }\n.weather-toggle-list input { accent-color: var(--se-accent); }\n.weather-opacity { display: grid; gap: 6px; margin-top: 10px; color: var(--se-dim); font: 550 .53rem/1.2 var(--se-mono); }\n.weather-opacity > span { display: flex; justify-content: space-between; gap: 8px; }\n.weather-opacity strong { color: var(--se-muted); }\n.weather-opacity input { width: 100%; accent-color: var(--se-accent); }\n.weather-status-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; margin-top: 10px; }\n.weather-status-grid > div { min-width: 0; display: grid; gap: 4px; padding: 7px; border: 1px solid var(--se-line); border-radius: 8px; background: rgba(0,0,0,.12); }\n.weather-status-grid span { color: var(--se-dim); font: 550 .48rem/1 var(--se-mono); text-transform: uppercase; letter-spacing: .05em; }\n.weather-status-grid strong { font: 650 .52rem/1 var(--se-mono); }\n.weather-status-grid small { overflow: hidden; color: var(--se-muted); font: 500 .47rem/1.25 var(--se-mono); text-overflow: ellipsis; white-space: nowrap; }\n.weather-status--ready { color: var(--se-success); }\n.weather-status--loading { color: var(--se-accent); }\n.weather-status--unavailable { color: var(--se-warning); }\n.weather-status--idle { color: var(--se-dim); }\n.weather-note,\n.weather-warning { margin: 9px 0 0; font-size: .54rem; line-height: 1.45; }\n.weather-note { color: var(--se-dim); }\n.weather-warning { color: var(--se-warning); }\n.weather-attribution {\n  display: inline-block;\n  margin-top: 8px;\n  color: var(--se-muted);\n  font: 550 .49rem/1.2 var(--se-mono);\n  text-decoration: none;\n}\n.weather-attribution:hover { color: var(--se-accent); }\n.layer-list--compact .weather-controls { margin-left: 0; margin-right: 0; }\n@media (max-width: 760px) {\n  .weather-controls { padding: 11px; }\n  .weather-toggle-list label { min-height: 44px; }\n}\n'.strip() + '\n', encoding='utf-8')
readme_path = Path('README.md')
readme = readme_path.read_text(encoding='utf-8')
phase17_readme = '## Living Earth — v1.2\n\nSignal Earth now includes a first-class Weather layer with NASA EOSDIS/GIBS VIIRS cloud optical thickness, optional GPM IMERG 30-minute precipitation, NASA EONET severe-storm tracks, simulation-time-aware observation requests, bounded recent fallback, and surfaced observation timestamps. Weather imagery is near-real-time observed context, not a forecast.\n'
if '## Living Earth — v1.2' not in readme:
    readme_path.write_text(readme.rstrip() + '\n\n' + phase17_readme + '\n', encoding='utf-8')
pkg_path = Path('package.json')
pkg = json.loads(pkg_path.read_text(encoding='utf-8'))
pkg['version'] = '1.2.0'
pkg_path.write_text(json.dumps(pkg, indent=2) + '\n', encoding='utf-8')
print('Phase 17 patch applied.')
